import clsx from 'clsx';
import { useMemo, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { isPersonalBizNo } from '~/entities/business/lib/validate-biz-no';
import { StepBeforeRegister } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { PATHS } from '~/shared/routes/paths';

type LocationState = {
  step?: StepBeforeRegister;
  aliasNm?: string;
};

// 사업자등록번호 3-2-5 자리
const SEGMENT_LENGTHS = [3, 2, 5] as const;

export const BusinessNumberPage = () => {
  const { navigate, navigateBack } = useNavigate();
  const { openAlertDialog } = useAlertDialog();
  const { step, aliasNm } = ((useLocation().state as LocationState | null) ?? {}) as LocationState;
  const [segments, setSegments] = useState<string[]>(['', '', '']);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  useSetHeaderTitle(i18n.t('manageBusinessAccount'));

  const businessNumber = segments.join('');
  const isComplete = useMemo(
    () => segments.every((value, index) => value.length === SEGMENT_LENGTHS[index]),
    [segments],
  );

  const handleChange = (index: number) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value.replace(/[^0-9]/g, '').slice(0, SEGMENT_LENGTHS[index]);

    setSegments((prev) => prev.map((item, i) => (i === index ? value : item)));

    // 자리수를 다 채우면 다음 칸으로 포커스를 넘긴다
    if (value.length === SEGMENT_LENGTHS[index]) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (index: number) => (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Backspace' && !segments[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handleNext = () => {
    if (!isComplete) return;

    // 법인 번호는 등록 대상이 아니므로 다음 화면으로 넘기기 전에 거른다
    if (!isPersonalBizNo(businessNumber)) {
      openAlertDialog({
        title: i18n.t('notification'),
        message: i18n.t('text:personalBusinessOnly'),
        buttonLabel: [i18n.t('skip'), i18n.t('confirm')],
        // 확인: 팝업만 닫고 번호를 다시 입력하도록 머무른다
        onCancelClick: () => navigateBack(),
      });
      return;
    }

    navigate(PATHS.myWallet.business, {
      state: { step: step ?? StepBeforeRegister.등록, aliasNm, businessNumber },
    });
  };

  return (
    <div className="page-business-register-KBB has-fixed-bottom">
      <div className="business-register-main">
        <section className="business-register-title-container">
          <h2 className="page-title">{i18n.t('createBusinessAccount')}</h2>
          <p className="page-desc">
            개인사업자만 등록 가능합니다.
            <br />
            사업자 정보 등록 시 현금영수증 발행이 가능합니다.
          </p>
        </section>

        <section className="business-register-form-container">
          <div className="form-item">
            <label className="form-label" htmlFor="bizNum1">
              {i18n.t('businessNumber')}
            </label>
            <div className="business-number-inputs">
              {SEGMENT_LENGTHS.map((length, index) => (
                <div key={length} className={clsx('input-item', 'common-input-field', `flex-${index + 1}`)}>
                  <input
                    type="text"
                    inputMode="numeric"
                    id={`bizNum${index + 1}`}
                    className="common-form-input"
                    placeholder={`${length}자리`}
                    maxLength={length}
                    value={segments[index]}
                    onChange={handleChange(index)}
                    onKeyDown={handleKeyDown(index)}
                    ref={(element) => (inputRefs.current[index] = element)}
                  />
                </div>
              ))}
            </div>
          </div>
        </section>
      </div>

      <div className="fixed-bottom-btn-wrapper">
        <button
          type="button"
          className={clsx('btn-confirm-bottom', !isComplete && 'disabled')}
          disabled={!isComplete}
          onClick={handleNext}
        >
          {i18n.t('next')}
        </button>
      </div>
    </div>
  );
};
